import { Form } from '@/components/ui/form';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { useEffect, useState } from 'react';
import { Employee } from '@/types/employee.types';
import { LetterRequest } from '@/features/selfServices/types/letterRequest.types';
import { SecondaryButton } from '@/components/buttons/SecondaryButton';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { toast } from 'sonner';
import TextInputForm from '@/components/forms/TextInputForm';
import { AddLetterFormValues, AddLetterSchema } from '../schemas/services/add-letter-schema';
import { useSelfServiceEmployee } from '@/features/selfServices/context/SelfServiceEmployeeContext';
import TextAreaInputForm from '@/components/forms/TextAreaInputForm';
import FileInput from './FileInput';
import { useNavigate } from 'react-router-dom';

interface Props {
    employee?: Employee | null;
    editingRecord?: LetterRequest | null;
    setAddLetter: (value: boolean) => void;
    handleRefreshTable: () => void;
}

const emptyLetterForm: Partial<AddLetterFormValues> = {
    letter_for: '',
    note: '',
    attachment: undefined,
};

export default function AddLetterForm({ employee, editingRecord, setAddLetter, handleRefreshTable }: Props) {
    const { effectiveEmployeeId, needsEmployeeSelection } = useSelfServiceEmployee();
    const [error, setError] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const navigate = useNavigate();

    const form = useForm<AddLetterFormValues>({
        resolver: zodResolver(AddLetterSchema),
        defaultValues: emptyLetterForm,
    });

    useEffect(() => {
        if (editingRecord) {
            form.reset({
                letter_for: editingRecord.letter_for,
                note: editingRecord.note || '',
                attachment: undefined,
            });
        } else {
            form.reset(emptyLetterForm);
        }
    }, [editingRecord, form]);

    const onSubmit = async (data: AddLetterFormValues) => {
        setLoading(true);
        setError(null); // Clear previous errors

        const isEdit = editingRecord != null;
        if (!isEdit && !employee && (!effectiveEmployeeId || needsEmployeeSelection)) {
            toast.error('يرجى اختيار الموظف أولاً.');
            setLoading(false);
            return;
        }
        try {
            const fd = new FormData();
            fd.append('letter_for', data.letter_for);
            fd.append('note', data.note);
            if (data.attachment instanceof File) {
                fd.append('attachment', data.attachment);
            }
            if (!isEdit && !employee && effectiveEmployeeId != null) {
                fd.append('employee_id', String(effectiveEmployeeId));
            }

            await apiPost({
                endpoint: isEdit ? endpoints.letterRequests.update + editingRecord!.id : endpoints.letterRequests.create,
                body: fd,
            });

            toast(isEdit ? 'تم تحديث الطلب بنجاح' : 'تم اضافة الطلب بنجاح');
            setAddLetter(false);
            handleRefreshTable();
            navigate('/self-services/services');
        } catch (error: any) {
            if (error.response?.data?.errors) {
                // Handle field-specific errors
                Object.entries(error.response.data.errors).forEach(([field, messages]) => {
                    form.setError(field as any, {
                        type: 'manual',
                        message: (messages as string[]).join(', '),
                    });
                });
            } else {
                // Handle generic error
                let errorMessage = 'حدث خطأ أثناء إرسال البيانات. يرجى المحاولة مرة أخرى.';
                if (error.response) {
                    errorMessage = error.response.data.msg || errorMessage;
                } else if (error.request) {
                    errorMessage = 'تعذر الاتصال بالخادم. يرجى التحقق من اتصالك بالإنترنت.';
                }
                setError(errorMessage);
            }
        } finally {
            setLoading(false);
        }
    };

    const isEditMode = editingRecord != null;

    return (
        <>
            <Form {...form}>
                <form onSubmit={form.handleSubmit(onSubmit)} className="mt-6">
                    {error && (
                        <div className="mb-4 p-4 bg-red-100 border border-red-400 text-red-700 rounded-lg">
                            <div className="flex justify-between items-center">
                                <span className="">{error}</span>
                                <button onClick={() => setError(null)} className="text-red-700 hover:text-red-900">
                                    ×
                                </button>
                            </div>
                        </div>
                    )}
                    <div className="grid grid-cols-1 gap-x-6">
                        <TextInputForm name="letter_for" label="الجهة الموجهه اليها" placeholder="شركة بن لادن" />
                        <TextAreaInputForm
                            className="flex flex-col min-h-[130px]"
                            name="note"
                            label="ملاحظات اضافية"
                            placeholder="اكتب ملاحظات اضافية"
                        />

                        <FileInput
                            name="attachment"
                            label="رفع ملف (اختياري)"
                            multiple={false}
                            maxSize={10 * 1024 * 1024}
                            existingAttachmentPath={editingRecord?.attachment ?? null}
                        />
                    </div>
                    <div className="flex flex-row gap-4 mt-12">
                        <SecondaryButton
                            onClick={() => setAddLetter(false)}
                            type="button"
                            className="w-full text-base leading-5 tracking-normal py-[10px] font-medium"
                        >
                            إلغاء
                        </SecondaryButton>
                        <PrimaryButton
                            type="submit"
                            className="w-full text-base leading-5 tracking-normal font-medium py-[10px]"
                        >
                            {loading ? 'جاري الحفظ...' : isEditMode ? 'حفظ التعديلات' : 'حفظ'}
                        </PrimaryButton>
                    </div>
                </form>
            </Form>
        </>
    );
}
